/* Anyaman Semesta — pengalaman belajar interaktif. Semua progres tersimpan lokal. */
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const STORE='anyamanSemesta_v2';
const state=(()=>{try{return JSON.parse(localStorage.getItem(STORE))||{completed:[],score:0,streak:0,best:0,works:[],badges:[],lastPage:'home',theme:'light',dailyDone:false}}catch{return {completed:[],score:0,streak:0,best:0,works:[],badges:[],lastPage:'home',theme:'light',dailyDone:false}}})();
state.theme='dark';document.documentElement.style.colorScheme='dark';
const save=()=>localStorage.setItem(STORE,JSON.stringify(state));
const toast=(s)=>{const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2500)};
const safe=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chapters=[
{title:'Matematika yang Hidup dan Bernapas',part:'Bagian I · Jalinan Tiga Pilar',summary:'Matematika bukan hanya rumus di buku. Ia hidup dalam pola cangkang keong, sarang lebah, kapal Phinisi, rumah adat, dan motif kain tradisional.',sections:[['Matematika ada di sekitar kita','Coba amati bentuk, pengulangan, jarak, dan keseimbangan yang muncul pada benda sehari-hari. Pola-pola itu dapat dipelajari secara matematis.'],['Etnomatematika','Etnomatematika mengkaji cara suatu kelompok budaya menggunakan ide matematika dalam kegiatan, karya, dan pengetahuan sehari-hari. Dalam Anyaman Semesta, motif batik menjadi pintu untuk mengamati geometri.'],['Tiga pilar Anyaman Semesta','Kearifan lokal: kain sebagai karya dan pengetahuan leluhur. Agama: keteraturan sebagai ruang refleksi nilai Tauhid dan Mizan. Teknologi: GeoGebra membantu menggambar dan menguji pola dengan presisi.'],['Matematika dan keseharian','Konsep matematika juga tampak pada gerak melingkar, pembagian, pengukuran, arah, dan perbandingan. Contoh dalam ibadah seperti arah kiblat dan tawaf memiliki konteks matematis tersendiri; pembahasannya perlu tetap mengikuti disiplin ilmu terkait.']],practice:'Temukan tiga benda di rumah yang memiliki pola berulang atau simetri. Gambarkan atau foto, lalu tulis: pola apa yang kamu lihat, apakah ada sumbu cermin, dan bagian mana yang berulang?',takeaway:'Matematika menjadi lebih bermakna ketika dihubungkan dengan kehidupan, budaya, dan pertanyaan yang kita amati sendiri.'},
{title:'Cerita dari Sehelai Kain',part:'Bagian II · Menyelami Motif',summary:'Kain tradisional dapat menjadi bahasa visual: warna, garis, bentuk, dan pengulangan menyampaikan identitas serta nilai yang hidup di masyarakat.',sections:[['Tiga dimensi makna','Dimensi estetis menyangkut rasa, warna, dan harmoni visual. Dimensi logis mengajak kita membaca geometri, simetri, dan pengulangan. Dimensi spiritual membuka ruang refleksi tentang Tauhid dan Mizan.'],['Aksara Lontara dan Sulapa’ Eppa','Aksara Lontara merupakan aksara tradisional Bugis-Makassar. Dalam materi buku, Sulapa’ Eppa dijelaskan melalui gagasan empat unsur dan bentuk belah ketupat. Hubungan bentuk dengan makna budaya perlu dipahami sebagai penafsiran yang bersumber, bukan sifat matematika yang otomatis berlaku pada semua aksara.'],['Rumah adat dan Passura’ Toraja','Rumah adat Tongkonan dan ragam ukiran Toraja menjadi konteks budaya yang dapat diamati. Pa’barre Allo dikaitkan dengan bentuk bulat dan sinar matahari; Pa’kapu’ Baka dengan gagasan ikatan atau anyaman. Motif harus diamati dari sumber visualnya sebelum sifat geometri ditetapkan.'],['Warna dan garis','Garis patah dapat mengarahkan perhatian pada sudut; lengkungan dapat diamati sebagai kurva; pola berulang dapat ditelaah dengan translasi atau rotasi. Makna warna dapat berbeda menurut konteks dan sumber, jadi jangan menganggap satu warna selalu mempunyai satu arti universal.']],practice:'Pilih satu kain atau gambar motif. Catat tiga hal yang benar-benar terlihat, lalu pisahkan pengamatan bentuk dari tafsiran maknanya. Cari sumber untuk mendukung tafsiran budaya.',takeaway:'Motif adalah karya budaya yang kaya. Membacanya dengan hormat berarti membedakan fakta visual, informasi sejarah, dan penafsiran.'},
{title:'Analisis Matematis: Membaca Pola dan Simetri',part:'Bagian II · Menyelami Motif',summary:'Transformasi geometri menjelaskan cara bentuk bergeser, dicerminkan, diputar, atau diperbesar. Pengubinan menyusun bentuk untuk menutup bidang.',sections:[['Refleksi (pencerminan)','Refleksi mencerminkan titik terhadap garis. Jarak titik dan bayangannya ke sumbu sama, dan ruas yang menghubungkan keduanya tegak lurus sumbu refleksi. Refleksi mempertahankan ukuran dan bentuk.'],['Rotasi (perputaran)','Rotasi memutar bentuk mengelilingi pusat dengan sudut tertentu. Satu putaran penuh adalah 360°. Jika ada delapan posisi yang tersebar merata, sudut antarposisi adalah 360° ÷ 8 = 45°.'],['Translasi (pergeseran)','Translasi memindahkan setiap titik dengan vektor yang sama. Bentuk, ukuran, dan orientasi tetap. Pola berulang pada kain dapat ditelaah sebagai translasi jika bukti visualnya mendukung.'],['Dilatasi (perubahan skala)','Dilatasi memakai faktor skala k. Jika semua panjang dikalikan 2, panjang menjadi 2 kali dan luas menjadi 2² = 4 kali. Untuk k negatif, arah terhadap pusat juga berubah; pada kegiatan awal, gunakan k positif agar lebih mudah.'],['Tessellation (pengubinan)','Pengubinan menutup bidang tanpa celah dan tanpa tumpang tindih. Untuk poligon beraturan yang bertemu di satu titik, sudut-sudutnya harus berjumlah 360°. Segitiga sama sisi: 6 × 60° = 360°; persegi: 4 × 90° = 360°; segilima beraturan: 360° ÷ 108° bukan bilangan bulat, sehingga tidak dapat mengubin sendiri dengan susunan sudut yang sama di satu titik.']],practice:'Di Studio Kreasi, ubah sudut rotasi menjadi 45°, 90°, lalu 180°. Bandingkan posisi pola. Setelah itu geser pola dengan vektor yang sama dan jelaskan mengapa bentuk tidak berubah.',takeaway:'Jangan hanya menebak transformasi dari nama motif. Perhatikan titik, sumbu, pusat, jarak, sudut, dan ukuran pada gambar.'},
{title:'Refleksi Keislaman: Tauhid dan Mizan',part:'Bagian II · Menyelami Motif',summary:'Keteraturan alam dan pola dapat menjadi bahan renungan tentang Tauhid dan Mizan. Hubungan spiritual merupakan refleksi nilai, bukan rumus geometri.',sections:[['Ayat qauliyah dan kauniyah','Dalam istilah yang digunakan buku, ayat qauliyah merujuk pada firman Allah dalam kitab suci, sedangkan ayat kauniyah merujuk pada tanda kebesaran Allah di alam semesta. Matematika dapat menjadi salah satu cara untuk mengamati keteraturan alam.'],['Zikir visual dan pengulangan','Pengulangan motif dapat mengingatkan pembaca pada ketekunan dan keteraturan. Ini merupakan analogi atau refleksi spiritual, bukan klaim bahwa setiap pengulangan motif secara otomatis adalah praktik ibadah.'],['Mizan sebagai keseimbangan','Mizan mengajak kita memikirkan keseimbangan dan keadilan. Pada pola, kita dapat menguji keseimbangan secara visual, misalnya membandingkan kiri-kanan atau distribusi bentuk. Pada kehidupan, maknanya lebih luas daripada simetri matematis.'],['Membaca kisah sebagai renungan','Kisah Daeng Parani dan I Tallo serta Nenek Bulo dalam buku menyajikan narasi untuk merenungkan alam, keteraturan, dan keseimbangan. Perlakukan kisah tersebut sebagai narasi pembelajaran dari buku kecuali ada sumber sejarah tambahan yang membuktikannya.']],practice:'Buat pola yang simetris dan pola yang sengaja tidak simetris. Bandingkan keduanya secara visual, lalu tulis satu paragraf tentang bagaimana gagasan keseimbangan dapat menjadi bahan refleksi dalam kehidupan.',takeaway:'Matematika membantu menjelaskan struktur; nilai spiritual mengajak kita merenungkan makna. Keduanya dapat berdialog tanpa mencampuradukkan jenis buktinya.'},
{title:'Visualisasi Teknologi dengan GeoGebra',part:'Bagian II · Menyelami Motif',summary:'GeoGebra membantu kita menggambar bentuk dasar, mencerminkan, memutar, dan menguji pola secara presisi.',sections:[['1. Siapkan kanvas','Buka GeoGebra Classic di browser. Aktifkan tampilan grafik dan perhatikan sumbu koordinat. Titik (0,0) dapat digunakan sebagai pusat pola.'],['2. Gambar bentuk dasar','Gunakan alat Polygon untuk membuat bentuk sederhana. Mulai dengan segitiga atau setengah bentuk agar langkahnya mudah diikuti.'],['3. Cerminkan bentuk','Pilih alat Reflect about Line. Klik poligon, lalu klik garis sumbu. Bandingkan jarak titik-titik yang bersesuaian terhadap sumbu.'],['4. Putar menggunakan slider','Buat slider sudut α dari 0° sampai 360°. Gunakan Rotate around Point dengan pusat (0,0). Uji 45°, 90°, dan 180°.'],['5. Eksperimen dan dokumentasikan','Ubah satu parameter pada satu waktu: sudut, skala, atau vektor geser. Catat apa yang berubah dan apa yang tetap. Jangan menyimpulkan motif asli memiliki transformasi tertentu hanya karena simulasi bisa dibuat.']],practice:'Buka GeoGebra, buat segitiga sederhana, cerminkan terhadap sumbu Y, lalu putar 90° terhadap titik asal. Simpan tangkapan layar dan tulis transformasi mana yang mempertahankan ukuran.',takeaway:'Teknologi menjadi jembatan antara pengamatan visual dan pengujian matematika yang dapat diulang.',link:'https://www.geogebra.org/classic'},
{title:'Kain sebagai Kitab Terbuka',part:'Bagian III · Titik Simpul',summary:'Buku mengajak pembaca merangkai kembali sains, budaya, dan agama melalui pengamatan motif dan kegiatan kreatif.',sections:[['Tiga sudut pandang','Sains membantu menguji pola dan transformasi. Budaya memberi konteks identitas dan sejarah. Agama memberi ruang untuk merenungkan nilai dan tujuan. Ketiganya dapat saling memperkaya dengan tetap menghargai cara pembuktian masing-masing.'],['Menjadi penemu makna','Mulailah dari pengamatan, ajukan pertanyaan, cari sumber, uji gagasan, lalu ceritakan hasilnya. Penemuan kecil yang dijelaskan dengan jujur lebih berharga daripada klaim besar tanpa bukti.'],['Ajakan akhir','Pilih satu kain atau motif di sekitarmu. Temukan satu pola atau simetri, catat apa yang kamu amati, dan ceritakan temuan itu kepada orang lain. Sertakan sumber jika kamu menjelaskan makna budaya.']],practice:'Selesaikan proyek mini: pilih motif, buat sketsa, jelaskan satu transformasi yang benar-benar terlihat, cantumkan sumber budaya, lalu tulis refleksi singkat tentang Mizan.',takeaway:'Anyaman Semesta mengajak kita melihat, bertanya, menguji, dan membuat—dengan rasa ingin tahu serta tanggung jawab.'}
];

/* Pendalaman bab: materi tambahan untuk memperluas pembelajaran 1–6. */
const chapterExtensions = [
[['Dari pengamatan ke model','Langkah awal pemodelan adalah memilih objek, menentukan pertanyaan, membuat representasi sederhana, lalu menguji apakah representasi itu sesuai dengan objek. Pada motif kain, satu bagian kecil dapat dipilih sebagai unit dasar; unit tersebut lalu dibandingkan dengan bagian lain.'],['Mengukur tanpa mengarang','Jika ingin menyatakan dua unsur sama besar, gunakan grid, penggaris, atau perbandingan piksel pada gambar. Jika perspektif foto miring atau kain berlipat, jelaskan keterbatasan pengukuran. Data visual yang tidak sempurna tidak boleh diperlakukan sebagai bukti presisi.'],['Aktivitas mini: jurnal pola','Buat tabel tiga kolom: objek yang diamati, ciri yang benar-benar terlihat, dan pertanyaan matematika. Contoh: “empat bentuk oval berulang”; pertanyaan: “apakah jarak antar pusatnya sama?” Tunda tafsiran budaya sampai sumbernya ditemukan.']],
[['Konteks, pembuat, dan pewarisan','Motif hidup di dalam praktik masyarakat. Nama, pemakaian, teknik, dan makna dapat berubah antarwilayah, komunitas, keluarga, atau perajin. Karena itu, satu gambar daring tidak cukup untuk mewakili seluruh tradisi sebuah daerah.'],['Membaca sumber secara kritis','Periksa siapa yang menerbitkan informasi, kapan diterbitkan, apakah sumber menyebut perajin atau komunitas, dan apakah makna yang disampaikan merupakan kutipan, ringkasan, atau interpretasi penulis. Catat sumber gambar terpisah dari sumber penjelasan budaya.'],['Aktivitas mini: kartu identitas motif','Buat kartu berisi nama motif, daerah yang disebut sumber, bahan/teknik bila tersedia, tautan sumber, dan tiga ciri visual. Tandai bagian yang belum diketahui dengan “perlu verifikasi”, bukan mengisinya dengan dugaan.']],
[['Koordinat dan transformasi','Dalam bidang koordinat, translasi dapat ditulis (x,y) → (x+a,y+b). Refleksi terhadap sumbu-x mengubah (x,y) menjadi (x,−y), sedangkan refleksi terhadap sumbu-y mengubahnya menjadi (−x,y). Rumus ini membantu memeriksa apakah hasil gambar sesuai dengan transformasi yang dimaksud.'],['Rotasi dan dilatasi','Rotasi 90° berlawanan arah jarum jam terhadap titik asal memetakan (x,y) menjadi (−y,x). Dilatasi berpusat di titik asal dengan faktor k memetakan (x,y) menjadi (kx,ky). Pada dilatasi, panjang berubah dengan faktor |k| dan luas berubah dengan faktor k².'],['Kongruen, sebangun, dan pengubinan','Bangun hasil refleksi, rotasi, dan translasi tetap kongruen dengan bangun awal. Dilatasi umumnya menghasilkan bangun sebangun: sudut-sudut bersesuaian sama, tetapi panjang berubah. Untuk menguji pengubinan, cek celah, tumpang tindih, dan jumlah sudut pada titik pertemuan.'],['Aktivitas mini: bukti visual','Pilih tiga titik yang mudah dikenali pada motif. Catat koordinat perkiraannya, lakukan satu transformasi di atas kertas atau Studio, lalu bandingkan jarak dan sudut sebelum-sesudah. Tulis langkah yang bisa diulangi orang lain.']],
[['Membedakan fakta dan refleksi','Pernyataan “pola ini mempunyai delapan unsur yang berjarak sudut sama” adalah klaim geometris yang dapat diuji. Pernyataan “pola ini mengingatkan saya pada keteraturan ciptaan” adalah refleksi pribadi. Keduanya dapat berdampingan, tetapi jenis bukti dan cara menyampaikannya berbeda.'],['Tauhid sebagai orientasi makna','Dalam pembelajaran ini, Tauhid menjadi landasan refleksi tentang keesaan Allah. Jangan menyatakan bahwa satu bentuk geometri tertentu secara otomatis membuktikan ajaran teologis. Jelaskan hubungan tersebut sebagai renungan atau tafsir yang perlu disertai rujukan keagamaan bila dibuat sebagai klaim formal.'],['Mizan: dari simetri ke tanggung jawab','Simetri adalah konsep geometri yang dapat diperiksa pada gambar. Keseimbangan dan keadilan dalam kehidupan merupakan gagasan etis yang lebih luas. Analogi visual bisa membuka diskusi, tetapi keputusan adil memerlukan pertimbangan konteks, hak, dan dampak terhadap manusia.'],['Aktivitas mini: refleksi dua kolom','Tulis satu kolom “hasil pengamatan matematika” dan satu kolom “renungan nilai”. Pastikan isi kolom pertama dapat diuji melalui gambar atau perhitungan; isi kolom kedua disampaikan sebagai refleksi dan tidak dipaksakan kepada semua pembaca.']],
[['Memulai konstruksi yang dapat diulang','Buka GeoGebra Classic, aktifkan sumbu dan grid, lalu buat titik dan poligon sederhana. Beri nama titik agar transformasi mudah dilacak. Simpan konstruksi dengan nama yang jelas supaya eksperimen bisa diperiksa kembali.'],['Perintah dasar untuk eksplorasi','Untuk translasi, tentukan vektor misalnya (3,0), lalu terapkan pada poligon. Untuk refleksi, gunakan garis sebagai sumbu. Untuk rotasi, tentukan pusat dan sudut; untuk dilatasi, pilih pusat dan faktor skala. Periksa hasilnya dengan membandingkan panjang sisi dan sudut.'],['Mencatat proses dan kesalahan','Ambil tangkapan layar sebelum dan sesudah transformasi, tulis nilai parameter, lalu jelaskan apa yang berubah dan tetap. Jika hasil berbeda dari dugaan, periksa urutan klik, satuan sudut, titik pusat, dan vektor. Kesalahan konstruksi adalah kesempatan untuk memperbaiki model.'],['Aktivitas mini: pola modular','Buat satu unit geometri, lalu salin dengan translasi ke kanan dan ke atas. Tambahkan rotasi untuk membentuk komposisi. Jelaskan bagian mana yang merupakan keputusan desain pribadi dan bagian mana yang meniru sumber visual tertentu.']],
[['Proyek akhir: dari motif ke cerita','Pilih satu motif yang sumbernya dapat dilacak. Kumpulkan gambar yang boleh digunakan, nama dan wilayah sebagaimana ditulis sumber, serta catatan tentang teknik atau makna jika tersedia. Jika informasi belum ditemukan, nyatakan batas tersebut secara terbuka.'],['Laporan mini yang bertanggung jawab','Susun laporan dengan bagian: tujuan, sumber dan izin gambar, deskripsi visual, konsep matematika, langkah pengujian, refleksi nilai, dan kesimpulan. Pisahkan data dari dugaan. Jangan menyebut desain buatan sendiri sebagai motif tradisional autentik.'],['Rubrik penilaian mandiri','Nilai diri pada empat aspek: ketelitian pengamatan, ketepatan matematika, kualitas sumber, dan kejelasan penjelasan. Perbaiki bagian yang belum didukung bukti. Kreativitas penting, tetapi tidak menggantikan ketepatan dan penghormatan terhadap komunitas budaya.'],['Tantangan lanjutan','Bandingkan dua motif dari daerah berbeda. Catat kesamaan bentuk tanpa menyimpulkan keduanya memiliki asal-usul yang sama. Cari sumber terpisah, lalu jelaskan apa yang dapat dan tidak dapat disimpulkan dari bukti yang tersedia.']]
];
chapterExtensions.forEach((sections,i)=>chapters[i].sections.push(...sections));

// Pendalaman tambahan untuk tiap bab: contoh, cara menguji, dan sumber belajar lanjutan.
const chapterFurther = [
  {sections:[['Dari benda nyata ke model matematika','Model adalah penyederhanaan yang dibuat untuk menjawab pertanyaan tertentu. Foto kain dapat dipotong menjadi unit pola, lalu unit itu digambar ulang pada grid. Model yang baik menyebut asumsi: misalnya kain dianggap datar, foto tidak miring, dan skala gambar konsisten.'],['Pola, barisan, dan pengulangan','Jika jarak antarpusat motif berulang tetap, posisi pusat dapat dimodelkan sebagai barisan aritmetika. Misalnya xₙ = x₁ + (n−1)d, dengan d sebagai jarak antarunit. Rumus hanya layak digunakan jika pengukuran menunjukkan jarak yang cukup konsisten.'],['Latihan investigasi','Pilih satu gambar motif. Tandai lima unit yang tampak berulang. Ukur jarak antarpusatnya, hitung selisih berturut-turut, lalu tulis apakah selisihnya mendekati tetap. Jelaskan faktor yang dapat membuat hasil pengukuran berbeda.']], resources:[['Etnomatematika – penelusuran publikasi','https://scholar.google.com/scholar?q=ethnomathematics+Indonesia'] ]},
  {sections:[['Batik, teknik, dan konteks','Batik merujuk pada tradisi menghias kain dengan teknik perintang warna menggunakan malam/lilin. Tidak semua kain bermotif dari Sulawesi otomatis merupakan batik; beberapa tradisi lokal lebih dikenal sebagai tenun atau ragam hias ukiran. Gunakan istilah sesuai sumber dan teknik yang dijelaskan.'],['Mencatat identitas motif secara bertanggung jawab','Catatan galeri idealnya memisahkan nama motif, komunitas/daerah, teknik, deskripsi visual, tafsiran makna, nama pembuat atau narasumber bila tersedia, sumber gambar, serta lisensi. Jika sumber tidak menjelaskan satu unsur, tulis “belum ditemukan” alih-alih membuat keterangan baru.'],['Latihan membandingkan sumber','Cari satu motif pada dua sumber berbeda. Tandai informasi yang sama, informasi yang berbeda, dan informasi yang hanya muncul pada satu sumber. Berikan tingkat keyakinan berdasarkan kedekatan sumber dengan perajin atau lembaga budaya.']], resources:[['UNESCO – Indonesian Batik','https://ich.unesco.org/en/RL/batik-00170'],['iWareBatik – Sulawesi Selatan','https://www.iwarebatik.org/south-sulawesi/?lang=id'],['Museum Batik Indonesia','https://iha.kemenbud.go.id/portfolio/museum-batik-indonesia/']]},
  {sections:[['Menguji simetri secara sistematis','Pilih satu titik khas dan bayangannya. Pada refleksi, ruas yang menghubungkan kedua titik tegak lurus sumbu dan sumbu membagi ruas itu menjadi dua sama panjang. Pada rotasi, jarak titik ke pusat tetap dan sudut putar sama untuk semua titik.'],['Vektor translasi dan jarak','Translasi dengan vektor (a,b) mengubah (x,y) menjadi (x+a,y+b). Jarak perpindahan adalah √(a²+b²). Jika unit motif bergeser 30 piksel ke kanan dan 0 piksel vertikal, vektornya (30,0) pada koordinat gambar; satuan piksel tidak otomatis sama dengan sentimeter pada kain.'],['Sudut, pengulangan, dan simetri putar','Jika suatu pola mempunyai n posisi yang sama jaraknya dalam satu putaran, sudut antarposisi adalah 360°/n. Ini baru berlaku jika pengamatan menunjukkan pengulangan putar yang teratur. Motif yang tampak hampir berulang karena foto terpotong belum cukup untuk memastikan simetri.'],['Latihan bukti geometri','Pilih satu motif dan buat tabel: klaim, bukti yang diamati, cara pengujian, hasil, dan keterbatasan. Contoh klaim “ada simetri refleksi”; bukti harus berupa pasangan titik yang berjarak sama terhadap sumbu, bukan hanya kesan bahwa gambar terlihat seimbang.']], resources:[['GeoGebra – Geometri','https://www.geogebra.org/geometry'],['GeoGebra – Transformasi','https://www.geogebra.org/search/transformations']]},
  {sections:[['Menghubungkan bentuk dengan refleksi nilai','Bentuk yang simetris bisa menjadi pemantik diskusi tentang keseimbangan, tetapi simetri matematis dan keadilan sosial bukan konsep yang identik. Refleksi keagamaan sebaiknya disampaikan sebagai ajakan berpikir, bukan sebagai bukti matematis yang menggantikan dalil atau penjelasan keilmuan.'],['Bahasa yang hati-hati saat menjelaskan budaya','Gunakan frasa “dalam sumber ini dijelaskan…”, “sebagian perajin menafsirkan…”, atau “bentuk ini mengingatkan pada…”. Hindari kata “selalu” atau “pasti” bila makna bisa beragam menurut komunitas dan konteks.'],['Latihan refleksi bertanggung jawab','Tulis 100–150 kata yang menghubungkan satu temuan geometri dengan nilai yang Anda renungkan. Pisahkan kalimat deskriptif dari kalimat reflektif, dan cantumkan sumber untuk klaim budaya atau agama yang bersifat faktual.']], resources:[['UNESCO – Batik Indonesia','https://ich.unesco.org/en/RL/batik-00170']]},
  {sections:[['Konstruksi langkah demi langkah','Mulai dari unit dasar, beri nama titik, buat sumbu atau pusat yang dibutuhkan, lalu terapkan satu transformasi pada satu waktu. Simpan setiap versi. Dengan cara ini, jika pola tidak sesuai, Anda dapat menemukan langkah yang menimbulkan kesalahan.'],['Mengukur dan membandingkan hasil','Untuk translasi, bandingkan vektor perpindahan titik-titik. Untuk rotasi, ukur jarak ke pusat dan sudut putar. Untuk dilatasi, bandingkan rasio panjang bersesuaian. Jangan mengandalkan tampilan visual saja ketika nilai numerik tersedia.'],['Tantangan desain modular','Rancang satu unit dengan 3–5 bentuk geometri, lalu ulangi dengan translasi. Buat versi kedua dengan rotasi. Beri keterangan mana yang terinspirasi oleh sumber tradisional dan mana yang merupakan rancangan baru Anda.']], resources:[['GeoGebra Classic','https://www.geogebra.org/classic'],['GeoGebra Geometry','https://www.geogebra.org/geometry']]},
  {sections:[['Membuat proyek mini yang bisa diperiksa','Pilih satu motif yang dapat dilacak ke sumber. Simpan tangkapan layar, tautan sumber, tanggal akses, dan catatan lisensi. Sertakan langkah matematika sehingga pembaca dapat mengulangi pengujian Anda.'],['Rubrik evaluasi proyek','Nilai proyek dari ketepatan konsep (0–4), bukti visual (0–4), kredibilitas sumber (0–4), kejelasan pemisahan fakta dan tafsir (0–4), serta kreativitas dan keterbacaan (0–4). Gunakan skor untuk menentukan bagian yang perlu diperbaiki, bukan hanya sebagai angka akhir.'],['Pertanyaan untuk diskusi lanjutan','Apa yang dapat disimpulkan dari bentuk motif? Apa yang belum dapat disimpulkan? Bagaimana sudut pandang perajin dapat melengkapi analisis visual? Bagaimana Anda memastikan foto yang digunakan sah untuk dipublikasikan?']], resources:[['Wikimedia Commons – Batik Indonesia','https://commons.wikimedia.org/wiki/Category:Batik_of_Indonesia'],['Museum Batik Indonesia','https://iha.kemenbud.go.id/portfolio/museum-batik-indonesia/']]}
];
chapterFurther.forEach((x,i)=>{chapters[i].sections.push(...x.sections);chapters[i].resources=x.resources;});


const motifs=[
{name:'Paqbarre Allo',region:'Toraja · Sulawesi Selatan',category:'Budaya lokal',image:'https://www.iwarebatik.org/wp-content/uploads/2020/01/1-1.png',source:'https://www.iwarebatik.org/paqbarre-allo/?lang=id',description:'Nama ini dijelaskan iWareBatik melalui kata “barre” (bulat) dan “allo” (matahari). Motif/ukiran dikaitkan dengan cahaya, ilmu, dan kebijaksanaan; pusatnya menampilkan kepala kerbau yang menjadi simbol kemuliaan dalam konteks Toraja.',math:'Amati lingkaran, pusat, dan kemungkinan susunan radial. Rotasi hanya dapat dinyatakan jika unsur visualnya benar-benar berulang dengan jarak sudut yang sama.',question:'Jika ada 8 unsur yang tersebar merata mengelilingi pusat, berapa sudut antarunsur?',answer:'45° karena 360° ÷ 8 = 45°.',alt:'Foto motif Paqbarre Allo dari iWareBatik'},
{name:'Aksara Lontara',region:'Bugis–Makassar · Sulawesi Selatan',category:'Aksara & identitas',image:'https://www.iwarebatik.org/wp-content/uploads/2020/01/2-1.png',source:'https://www.iwarebatik.org/lontara/?lang=id',description:'iWareBatik menjelaskan Lontara sebagai aksara tradisional komunitas Bugis dan Makassar. Motif berbasis aksara menghubungkan identitas literasi dengan desain kain. Makna khusus tiap desain perlu dirujuk pada perajin atau sumber yang membahas desain tersebut.',math:'Bandingkan garis, sudut, orientasi, dan pengulangan. Tidak semua karakter Lontara memiliki simetri refleksi atau rotasi; uji setiap bentuk secara terpisah.',question:'Jika sebuah bentuk tidak berhimpit dengan bayangannya ketika dicerminkan, apakah ia memiliki simetri refleksi pada sumbu itu?',answer:'Tidak. Simetri refleksi hanya ada jika bentuk dan bayangannya berhimpit.',alt:'Foto motif Lontara dari iWareBatik'},
{name:'La Galigo',region:'Bugis · Sulawesi Selatan',category:'Sastra & cerita',image:'https://www.iwarebatik.org/wp-content/uploads/2020/01/4-1-400x250.png',source:'https://www.iwarebatik.org/la-galigo/?lang=id',description:'La Galigo adalah karya sastra epik Bugis yang menginspirasi perajin dalam menciptakan motif. iWareBatik mengaitkannya dengan kisah Sangiang Serri. Bentuk visual motif yang dipilih bisa berbeda-beda menurut desain perajin.',math:'Baca motif sebagai komposisi visual terlebih dahulu. Cari pengulangan, arah garis, atau bentuk yang kongruen, lalu dokumentasikan bukti pada gambar.',question:'Apa langkah paling tepat sebelum menyebut motif memiliki translasi?',answer:'Temukan unsur yang berulang dan tunjukkan bahwa setiap titik berpindah dengan vektor yang sama.',alt:'Foto motif La Galigo dari iWareBatik'},
{name:'Tongkonan',region:'Toraja · Sulawesi Selatan',category:'Arsitektur & ornamen',image:'https://www.iwarebatik.org/wp-content/uploads/2020/01/3-1-400x250.png',source:'https://www.iwarebatik.org/tongkonan/?lang=id',description:'Tongkonan adalah rumah tradisional Toraja. Bentuk arsitektur dan ornamen Tongkonan menginspirasi desain tekstil. Motif yang mengambil inspirasi Tongkonan perlu dibedakan dari foto bangunan aslinya.',math:'Amati garis atap, keseimbangan visual, bentuk berulang, dan kemungkinan refleksi pada bagian tertentu. Simetri visual tidak selalu sempurna karena bahan dan pengerjaan dapat berbeda.',question:'Jika sisi kiri dan kanan atap tampak serupa, apa yang perlu diperiksa untuk menguji refleksi?',answer:'Tentukan garis sumbu dan bandingkan jarak titik-titik bersesuaian terhadap sumbu.',alt:'Foto motif Tongkonan dari iWareBatik'},
{name:'Pa’tedong',region:'Toraja · Sulawesi Selatan',category:'Motif kerbau',image:'https://www.iwarebatik.org/wp-content/uploads/2020/01/1-1-400x250.png',source:'https://www.iwarebatik.org/south-sulawesi/?lang=id',description:'Pa’tedong berarti kepala kerbau. Sumber iWareBatik menjelaskan kerbau sebagai simbol kemuliaan dan kemakmuran dalam konteks motif Toraja. Bentuk dan makna desain dapat berbeda sesuai interpretasi perajin.',math:'Bila gambar kepala kerbau memiliki sisi kiri dan kanan yang saling memantul, sumbu refleksi dapat diuji melalui garis tengah. Jangan mengasumsikan semua gambar mempunyai simetri sempurna.',question:'Bagaimana menguji simetri refleksi kepala kerbau?',answer:'Tarik garis tengah lalu bandingkan pasangan titik kiri-kanan dan jaraknya ke garis tersebut.',alt:'Ilustrasi motif Pa’tedong terkait budaya Toraja'},
{name:'Motif Pa’kapu’ Baka',region:'Toraja · motif ikatan',category:'Anyaman & pola',image:'https://www.iwarebatik.org/wp-content/uploads/2020/01/3-1-400x250.png',source:'https://www.iwarebatik.org/south-sulawesi/?lang=id',description:'Dalam materi Anyaman Semesta, Pa’kapu’ Baka dibahas sebagai motif ikatan bakul. Penafsiran visual dan maknanya sebaiknya dicocokkan dengan gambar dan rujukan budaya yang lebih spesifik sebelum digunakan sebagai klaim final.',math:'Perhatikan jalur yang saling bertaut dan pengulangan unit. Jika unit bergeser dengan jarak dan arah sama, pola dapat dianalisis melalui translasi.',question:'Apa ciri translasi pada pola berulang?',answer:'Setiap titik berpindah dengan vektor yang sama; ukuran dan orientasi bentuk tetap.',alt:'Ilustrasi motif Toraja yang dipakai sebagai referensi pola'},
{name:'Pa’sulan Treng',region:'Toraja · garis silang',category:'Pola garis',image:'https://www.iwarebatik.org/wp-content/uploads/2020/01/2-1.png',source:'https://www.iwarebatik.org/south-sulawesi/?lang=id',description:'Materi buku menyebut Pa’sulan Treng sebagai garis diagonal bersilang. Kartu ini digunakan sebagai titik awal eksplorasi; gambar spesifik dan makna tradisionalnya perlu diverifikasi melalui sumber motif yang sesuai.',math:'Amati sudut perpotongan, kemiringan, dan pengulangan. Dua garis yang bersilang tidak otomatis membentuk simetri; periksa keseluruhan motif.',question:'Apakah dua garis yang bersilang otomatis membuat seluruh motif simetris?',answer:'Tidak. Simetri harus diuji pada keseluruhan bentuk terhadap sumbu atau pusat tertentu.',alt:'Referensi visual pola Lontara dan garis pada iWareBatik'}
,{name:'Tenun Sutra Bugis–Makassar',region:'Bugis–Makassar · Sulawesi Selatan',category:'Anyaman & pola',image:'',source:'https://www.iwarebatik.org/south-sulawesi/?lang=id',description:'Buku Anyaman Semesta memasukkan motif tenun sutra Bugis–Makassar dalam cakupan pembahasan tekstil Sulawesi Selatan. Karya ini menggunakan teknik tenun; istilah batik pada aplikasi mengikuti pengertian luas buku dan tidak menyamakan teknik tenun dengan batik malam.',math:'Amati susunan benang, garis, belah ketupat, dan pengulangan unit pada gambar kain yang dirujuk. Uji translasi atau refleksi hanya jika pola visualnya mendukung.',question:'Apa yang perlu dibedakan ketika mengamati tenun sutra?',answer:'Bedakan teknik pembuatan kain, bentuk motif yang terlihat, dan makna budaya yang dijelaskan oleh sumber.',alt:'Ilustrasi edukatif untuk motif tenun sutra Bugis–Makassar'},
{name:'Tenun Sutra Mandar',region:'Mandar · cakupan tekstil dalam buku',category:'Anyaman & pola',image:'',source:'https://www.iwarebatik.org/south-sulawesi/?lang=id',description:'Buku Anyaman Semesta juga membahas motif tenun sutra Mandar dalam cakupan tekstil yang dipelajari. Kartu ini menegaskan konteks tenun Mandar sebagaimana cakupan buku; teknik tenun tidak disamakan dengan batik malam dan canting.',math:'Perhatikan garis, susunan benang, pola berulang, dan keseimbangan bidang pada foto kain. Tentukan transformasi geometri berdasarkan bukti visual, bukan hanya nama motif.',question:'Mengapa tenun Mandar tetap relevan dalam galeri aplikasi ini?',answer:'Karena buku menggunakan pengertian batik secara luas untuk membahas ragam motif tekstil Sulawesi, termasuk motif tenun Mandar.',alt:'Ilustrasi edukatif untuk motif tenun sutra Mandar'},

];

